mapper.select:
SELECT a.id, a.user_id, a.session_id, a.matched, a.similarity, a.match_threshold, a.reject_threshold, a.model_version, a.challenge_action, a.source, a.baseline_count, a.best_baseline_id, a.probe_face_detected, a.probe_image_urls, a.best_baseline_image_url, a.top_sims_json, a.created_at, p.name AS user_name FROM face_verify_audit a
LEFT JOIN aro_personnel p ON a.user_id = p.user_id
ORDER BY a.created_at DESC, a.id DESC LIMIT #{limit} OFFSET #{offset}
